const shadowInfo = await browserjs(tabId, () => {
  function findInShadow(node, fn) {
    let matches = [];
    if (fn(node)) matches.push(node);
    if (node.shadowRoot) {
      matches = matches.concat(findInShadow(node.shadowRoot, fn));
    }
    for (let child of (node.children || [])) {
      matches = matches.concat(findInShadow(child, fn));
    }
    return matches;
  }

  const allRadios = findInShadow(document.body, n => n.getAttribute && (n.getAttribute('role') === 'radio' || n.type === 'radio'));
  return allRadios.map(r => ({
    tag: r.tagName,
    text: r.textContent?.trim(),
    value: r.value,
    role: r.getAttribute('role')
  }));
});

