const tabId = 730410078;

const urlsAndPanels = await browserjs(tabId, async () => {
  const host = document.querySelector('results-view');
  // We can call host.changePanel or inspect what host.answers are:
  const answers = host.answers;
  // Let's see what panels can be loaded
  const panels = ["goals", "joy", "exercise", "eating", "struggles"];

  // Let's test calling changePanel on each or fetching their content
  const panelContents = {};
  for (const p of panels) {
    host.panel = p;
    await host.getContent().then(t => { host.content = t; });
    panelContents[p] = host.content;
  }

  // Reset back to joy or goals
  return {
    answers,
    panelContents
  };
});

console.log("Answers:", JSON.stringify(urlsAndPanels.answers, null, 2));
for (const p of Object.keys(urlsAndPanels.panelContents)) {
  console.log(`=== Panel: ${p} ===`);
  console.log(JSON.stringify(urlsAndPanels.panelContents[p], null, 2));
}

